    if (fx.length) f.effects = fx.map(([x, y, b, s, c]) => { const col = Array.isArray(c) ? c : [c, 1]; return { type: 'DROP_SHADOW', color: { ...rgb(col[0]), a: col[1] }, offset: { x, y }, radius: b, spread: s, visible: true, blendMode: 'NORMAL' }; });
    f.clipsContent = !!clip;
